# Biblioteca de gramática: tag -> título, fórmula (partes entre [ ] são destacadas), regra, exemplos "en=pt", erros comuns "errado=certo"
def G(t, f, r, ex, mist, tip=''):
    return dict(t=t, f=f, r=r, ex=[tuple(x.split('=', 1)) for x in ex.split('|')], mist=[tuple(x.split('=', 1)) for x in mist.split('|')], tip=tip)
GR = {
'greet': G("Cumprimentos e despedidas", "[Good] + [morning / afternoon / evening]", "Use Good morning até o meio-dia, Good afternoon à tarde e Good evening ao chegar à noite. Good night só se despede (hora de dormir).", "Good morning!=Bom dia!|Good evening, Ana.=Boa noite, Ana.|Good night, sleep well.=Boa noite, durma bem.", "Good night! (ao chegar)=Good evening!|I am fine thank=I'm fine, thanks.", "Hi é informal; Hello serve para tudo."),
'name': G("I'm / My name is", "[I'm] + nome  |  [My name is] + nome", "I'm é a forma curta de I am. Para perguntar o nome: What's your name? (What's = What is).", "I'm Tom.=Eu sou o Tom.|My name is Ana.=Meu nome é Ana.|What's your name?=Qual é o seu nome?", "Me name is Tom.=My name is Tom.|I am call Ana.=I'm Ana. / My name is Ana.", "My (meu/minha) ≠ me (me/mim)."),
'from': G("Where are you from?", "[I'm from] + país/cidade", "From indica origem. Pergunta: Where are you from? Resposta curta: I'm from Brazil.", "I'm from Brazil.=Sou do Brasil.|She's from Egypt.=Ela é do Egito.|Where are you from?=De onde você é?", "I'm of Brazil.=I'm from Brazil.|I from Japan.=I'm from Japan.", "Em inglês o verbo to be é obrigatório: I'm from…"),
'numbers': G("Números e quantidades", "[number] + [noun in plural]", "Com mais de um, o substantivo vai ao plural (-s). Pergunte quantidade com How many + plural?", "Two apples.=Duas maçãs.|How many books?=Quantos livros?|I have ten pens.=Tenho dez canetas.", "Two apple.=Two apples.|How much books?=How many books?", "Thirteen (13) e thirty (30) têm sílaba forte diferente."),
'spell': G("Soletrar e dar dados", "[How do you spell] + palavra?", "Para pedir a grafia: How do you spell that? Diga as letras uma a uma. Em e-mails: at (@) e dot (.).", "How do you spell it?=Como se escreve?|H-A-N-A.=H-A-N-A.|It's mia at mail dot com.=É mia arroba mail ponto com.", "How you spell it?=How do you spell it?|My email is mia@mail.com (dito assim)=...mia at mail dot com", ""),
'polite': G("Cortesia", "[Can I have…, please?]  [Thank you]  [Sorry]", "Please vai no fim do pedido. Thank you agradece; You're welcome responde. Sorry pede desculpas e Excuse me chama a atenção.", "A coffee, please.=Um café, por favor.|Thank you very much.=Muito obrigado.|Excuse me, where is…?=Com licença, onde fica…?", "Give me a coffee.=A coffee, please.|Thanks you.=Thank you.", "Excuse me = antes de falar; Sorry = depois de errar."),
'thisthat': G("This / that / these / those", "[This / These] (perto)  |  [That / Those] (longe)", "This e that são singular; these e those são plural. Perto de você: this/these. Longe: that/those.", "This is my book.=Este é meu livro.|That is a clock.=Aquilo é um relógio.|These are pens.=Estes são canetas.", "This are my books.=These are my books.|That's pens.=Those are pens.", "'a' antes de consoante, 'an' antes de som de vogal."),
'adj': G("Adjetivo antes do substantivo", "[adjetivo] + [substantivo]", "Em inglês o adjetivo vem antes do substantivo e não muda para plural: a red car, two red cars.", "A red car.=Um carro vermelho.|Two big dogs.=Dois cachorros grandes.|The house is blue.=A casa é azul.", "A car red.=A red car.|Two bigs dogs.=Two big dogs.", "Com be, a cor vem depois: The car is red."),
'poss': G("my, your, his, her", "[my / your / his / her / our / their] + substantivo", "O possessivo concorda com o DONO, não com a coisa: his mother (mãe dele), her mother (mãe dela).", "My sister is tall.=Minha irmã é alta.|Her name is Kate.=O nome dela é Kate.|Their house is big.=A casa deles é grande.", "She is my brother.=She is my sister.|Her name is Tom (menino)=His name is Tom.", "'s = posse: Sara's bag (a bolsa da Sara)."),
'be': G("To be: am / is / are", "[I am] · [you are] · [he/she/it is] · [we/you/they are]", "Em inglês o verbo to be é obrigatório. Formas curtas: I'm, you're, he's, she's, it's, we're, they're.", "I am happy.=Estou feliz.|She is a doctor.=Ela é médica.|They are ready.=Eles estão prontos.", "I happy.=I am happy.|She are tired.=She is tired.|We is friends.=We are friends.", "To be vale para ser E estar."),
'beq': G("Perguntas e negativas com be", "[Am/Is/Are] + sujeito?   |   sujeito + [am/is/are] + [not]", "Para perguntar, inverta: Are you…? Para negar, coloque not: isn't, aren't, I'm not. Resposta curta: Yes, I am / No, I'm not.", "Are you OK?=Você está bem?|It isn't late.=Não está tarde.|Yes, I am.=Sim, estou.", "You are OK?=Are you OK?|He no is here.=He isn't here.|Yes, I'm.=Yes, I am.", "Nunca use a forma curta no 'Yes': Yes, I am."),
'job': G("a / an + profissão", "I'm [a / an] + profissão", "Use a antes de consoante (a teacher) e an antes de som de vogal (an engineer). Pergunta: What do you do?", "I'm a teacher.=Sou professor.|She's an engineer.=Ela é engenheira.|What do you do?=O que você faz?", "I'm teacher.=I'm a teacher.|I'm a engineer.=I'm an engineer.", ""),
'days': G("Dias e preposições de tempo", "[on] + dia  |  [in] + mês  |  [at] + hora", "Use on com dias (on Monday), in com meses e anos (in May) e at com horas (at nine). Dias começam sempre com letra maiúscula.", "On Monday I work.=Na segunda eu trabalho.|In May it rains.=Em maio chove.|At nine o'clock.=Às nove em ponto.", "In Monday=On Monday|At May=In May|monday=Monday", ""),
'date': G("Meses, datas e ordinais", "[month] + [ordinal]: May [tenth]", "Para datas usamos números ordinais: first, second, third, fourth… Dizemos on May tenth ou on the tenth of May.", "My birthday is on May tenth.=Meu aniversário é em 10 de maio.|It's October first.=É primeiro de outubro.|Today is the fifth.=Hoje é dia cinco.", "May ten=May tenth|The one of May=May first", "01/02 nos EUA = 2 de janeiro; no Brasil = 1º de fevereiro."),
'time': G("Que horas são?", "It's [number] + [o'clock / half past / quarter to]", "Hora cheia: It's three o'clock. Meia hora: half past three. Quinze: a quarter past / to. Evento: at + hora.", "It's two o'clock.=São duas horas.|Half past four.=Quatro e meia.|The train is at eight.=O trem é às oito.", "It's the two hours.=It's two o'clock.|At half four=At half past four", ""),
'ps1': G("Present simple: I / you / we / they", "sujeito + [verbo base]", "Para hábitos e rotinas use o verbo na forma base. Com advérbios (always, usually) o advérbio vem antes do verbo.", "I get up at six.=Levanto às seis.|They work here.=Eles trabalham aqui.|We eat lunch at noon.=Almoçamos ao meio-dia.", "I am get up.=I get up.|We goes home.=We go home.", ""),
'ps3': G("Present simple: he / she / it", "he/she/it + [verbo + s]", "Com he, she e it o verbo ganha -s (-es em go, watch, wash, fix; y → ies em study). Negativa: doesn't + verbo base.", "She wakes up early.=Ela acorda cedo.|He goes to work.=Ele vai ao trabalho.|It doesn't rain here.=Aqui não chove.", "She wake up.=She wakes up.|He doesn't works.=He doesn't work.", "have → has."),
'doq': G("Do / does em perguntas", "[Do] + I/you/we/they + verbo?   [Does] + he/she/it + verbo?", "Em perguntas use do/does + verbo na base. Resposta curta: Yes, I do. / No, he doesn't.", "Do you like pasta?=Você gosta de macarrão?|Does she work here?=Ela trabalha aqui?|Where do they live?=Onde eles moram?", "Does she works?=Does she work?|You like pasta?=Do you like pasta?", ""),
'food': G("Gostar e pedir: like / I'd like", "[I like] + algo  |  [I'd like] + algo, please", "I like fala de gosto geral. I'd like (I would like) é o jeito educado de pedir algo.", "I like soup.=Gosto de sopa.|I'd like a coffee.=Eu gostaria de um café.|Do you like fish?=Você gosta de peixe?", "I want a coffee please (seco)=I'd like a coffee, please.|I like to soup.=I like soup.", ""),
'wouldlike': G("Would like / want / need", "[want] (querer) · [need] (precisar) · [would like] (gostaria)", "Want e need são diretos. Would like é mais educado e comum em lojas, restaurantes e pedidos formais.", "I want a new phone.=Quero um celular novo.|I need some help.=Preciso de ajuda.|I'd like to order.=Gostaria de pedir.", "I would to order.=I'd like to order.|I need to help.=I need help.", ""),
'somany': G("Some, any, much, many, a lot of", "[some] (afirmativas) · [any] (perguntas/negativas) · [much/many] (quantidade)", "Many com contáveis (many books). Much com incontáveis (much water). A lot of serve para os dois. Some em afirmativas, any em perguntas e negativas.", "We need some milk.=Precisamos de leite.|Do you have any eggs?=Você tem ovos?|How much water? How many cups?=Quanta água? Quantos copos?", "I don't have some money.=I don't have any money.|How many water?=How much water?", "Contáveis: apple/apples; incontáveis: water, rice, money."),
'price': G("Preços e dinheiro", "How much [is / are] + coisa?", "How much is… (singular) e How much are… (plural). Preços usam dollars/euros no plural.", "How much is this scarf?=Quanto custa este lenço?|They're six dollars.=Custam seis dólares.|It's too expensive.=É caro demais.", "How much cost?=How much is it?|It is six dollar.=It is six dollars.", ""),
'there': G("There is / there are", "[There is] + singular  |  [There are] + plural", "Use there is (there's) com singular ou incontável, e there are com plural. Pergunta: Is there…? / Are there…?", "There is a sofa.=Há um sofá.|There are two beds.=Há duas camas.|Is there a garden?=Há um jardim?", "There have a sofa.=There is a sofa.|There is two beds.=There are two beds.", ""),
'prep': G("Preposições: in / on / at", "[in] (dentro) · [on] (sobre) · [at] (ponto exato)", "In = dentro de espaços e meses; on = sobre superfícies e dias; at = ponto exato e horas. Também: under, behind, next to, between.", "The keys are in the bag.=As chaves estão na bolsa.|The book is on the table.=O livro está sobre a mesa.|I'm at school.=Estou na escola.", "The book is in the table.=The book is on the table.|I'm in school at 9 (ponto)=I'm at school at nine.", ""),
'dir': G("Direções", "[Turn left/right] · [Go straight] · [It's next to…]", "Para dar direções use o imperativo (verbo sem sujeito): Turn left, Go straight. Para dizer onde: next to, opposite, near.", "Turn left at the bank.=Vire à esquerda no banco.|Go straight for two blocks.=Siga em frente por dois quarteirões.|It's opposite the park.=Fica em frente ao parque.", "You turn to left.=Turn left.|Go straight on two blocks=Go straight for two blocks", ""),
'imper': G("Imperativo", "[verbo base] (+ please)  |  [Don't] + verbo base", "O imperativo usa o verbo sem sujeito: Open the door. Para negar: Don't + verbo. Please deixa o pedido educado.", "Open the window.=Abra a janela.|Don't touch it!=Não toque!|First, mix the eggs.=Primeiro, misture os ovos.", "You don't touch it.=Don't touch it.|Opens the window.=Open the window.", ""),
'can': G("Can e can't", "sujeito + [can / can't] + verbo base", "Can expressa habilidade e permissão; o verbo seguinte fica na base, sem to e sem -s: She can swim. Pergunta: Can you…?", "I can swim.=Sei nadar.|She can't drive.=Ela não sabe dirigir.|Can I open the window?=Posso abrir a janela?", "She cans swim.=She can swim.|I can to swim.=I can swim.", ""),
'likeing': G("Gostos: like / love / hate + verbo-ing", "[like / love / hate] + [verbo-ing]", "Depois de like, love, hate e enjoy, o verbo vai no -ing: I like cooking. Substantivo também serve: I like music.", "I love dancing.=Adoro dançar.|She hates waking up early.=Ela odeia acordar cedo.|Do you enjoy reading?=Você curte ler?", "I like cook.=I like cooking.|I hate to waking up.=I hate waking up.", ""),
'freq': G("Advérbios de frequência", "sujeito + [always / usually / sometimes / never] + verbo", "O advérbio vem antes do verbo principal e depois de be: I always eat breakfast; She is never late. Pergunta: How often…?", "I usually walk to work.=Costumo ir a pé ao trabalho.|He is never late.=Ele nunca se atrasa.|How often do you cook?=Com que frequência você cozinha?", "I eat always breakfast.=I always eat breakfast.|He never is late.=He is never late.", "100% always · usually · often · sometimes · rarely · never 0%"),
'goingto': G("Planos: be going to", "[am / is / are] + [going to] + verbo base", "Use para planos e intenções: I'm going to travel. Pergunta: Are you going to…? Em fala informal: gonna.", "I'm going to visit my friend.=Vou visitar meu amigo.|They're going to hike.=Eles vão fazer trilha.|Are you going to stay?=Você vai ficar?", "I going to travel.=I'm going to travel.|She is going to travels.=She is going to travel.", ""),
'wh': G("Perguntas com Wh-", "[What / Where / When / Who / Why / How] + do/does/did + sujeito + verbo?", "A palavra de pergunta vem primeiro; depois o auxiliar (do, does, did) e o sujeito: Where do you live?", "Where do you live?=Onde você mora?|What time does it start?=A que horas começa?|Why did she leave?=Por que ela saiu?", "Where you live?=Where do you live?|What time it starts?=What time does it start?", ""),
'comp': G("Comparativos", "adjetivo curto + [-er] + [than]  |  [more] + adjetivo longo + [than]", "Adjetivos curtos ganham -er (taller, cheaper); longos usam more (more beautiful). Irregulares: good → better, bad → worse.", "This is cheaper than that.=Este é mais barato que aquele.|She's taller than me.=Ela é mais alta que eu.|It's more interesting.=É mais interessante.", "more cheap=cheaper|taller that me=taller than me", ""),
'super': G("Superlativos", "[the] + adjetivo + [-est]  |  [the most] + adjetivo longo", "Use the antes do superlativo: the biggest, the best, the most beautiful. Irregulares: good → best, bad → worst.", "It's the highest mountain.=É a montanha mais alta.|She's the best teacher.=Ela é a melhor professora.|The most popular one.=A mais popular.", "It's biggest.=It's the biggest.|the most big=the biggest", ""),
'must': G("Regras: must, mustn't, can't", "[must] (obrigação) · [mustn't] (proibido) · [can't] (não pode)", "Must expressa obrigação forte; mustn't proíbe. Can't também diz que algo não é permitido. O verbo vem na base.", "You must stop.=Você deve parar.|You mustn't park here.=Não pode estacionar aqui.|We can't smoke inside.=Não podemos fumar aqui dentro.", "You must to stop.=You must stop.|You musts wear it.=You must wear it.", ""),
'pastbe': G("Passado de be: was / were", "[I/he/she/it was] · [you/we/they were]", "Was e were são o passado de am/is/are. Negativas: wasn't, weren't. Pergunta: Were you…? Was it…?", "I was at home.=Eu estava em casa.|They were happy.=Eles estavam felizes.|Was it good?=Foi bom?", "I were tired.=I was tired.|We was late.=We were late.", ""),
'pastreg': G("Passado regular: -ed", "verbo + [-ed]", "Verbos regulares ganham -ed (-d se terminam em e; y → ied). O passado é igual para todas as pessoas: I/he/we worked.", "I cooked dinner.=Cozinhei o jantar.|She called me.=Ela me ligou.|We visited a museum.=Visitamos um museu.", "I cook yesterday.=I cooked yesterday.|She calleds me.=She called me.", "-ed soa /t/, /d/ ou /ɪd/."),
'pastirr': G("Passado irregular", "go → [went] · see → [saw] · buy → [bought]", "Muitos verbos comuns não usam -ed: go → went, have → had, eat → ate. É preciso memorizá-los aos poucos.", "I went to the market.=Fui à feira.|She bought a book.=Ela comprou um livro.|We ate pizza.=Comemos pizza.", "I goed home.=I went home.|She buyed a hat.=She bought a hat.", ""),
'didq': G("Did em perguntas e negativas", "[Did] + sujeito + verbo base?   |   sujeito + [didn't] + verbo base", "No passado, perguntas e negativas usam did/didn't e o verbo volta à forma base: Did you see it? I didn't go.", "Did you see the fire?=Você viu o incêndio?|I didn't go there.=Não fui lá.|Where did she live?=Onde ela morava?", "Did you saw it?=Did you see it?|I didn't went.=I didn't go.", ""),
'usedto': G("Used to", "[used to] + verbo base", "Used to fala de hábitos ou situações do passado que não existem mais: I used to live here. Negativa: didn't use to.", "I used to swim every day.=Eu nadava todo dia.|There used to be a farm.=Havia uma fazenda.|Did you use to play?=Você costumava brincar?", "I use to live here.=I used to live here.|She didn't used to.=She didn't use to.", ""),
'conn': G("Conectores de história", "[and] · [but] · [so] · [because] · [when] · [then]", "And soma, but contrasta, so dá resultado, because dá motivo, when marca tempo, then indica sequência.", "She was hungry, so she ate.=Ela estava com fome, então comeu.|He was tired because he worked.=Ele estava cansado porque trabalhou.|First, then, finally.=Primeiro, depois, finalmente.", "I was tired but I slept.=I was tired, so I slept.|Because it rained, so I stayed.=Because it rained, I stayed.", ""),
'prescont': G("Presente contínuo", "[am / is / are] + [verbo-ing]", "Para o que acontece agora ou temporariamente: I'm reading. Ortografia: make → making, run → running.", "She is running.=Ela está correndo.|They're playing soccer.=Eles estão jogando futebol.|What are you doing?=O que você está fazendo?", "She running.=She is running.|I am reading a book now (am read)=I am reading.", "Verbos de estado (know, like, want) não usam -ing."),
'simvscont': G("Present simple × contínuo", "hábito: [verbo]  |  agora: [be + verbo-ing]", "Present simple = rotina (I work). Present continuous = agora/temporário (I'm working today). Palavras-chave: usually / now, today.", "I usually work here.=Geralmente trabalho aqui.|Today I'm working at home.=Hoje estou trabalhando em casa.|She never drinks coffee.=Ela nunca bebe café.", "I'm working every day.=I work every day.|I work now.=I'm working now.", ""),
'will': G("Will: ofertas, promessas, previsões", "sujeito + [will / won't] + verbo base", "Will expressa decisões na hora (I'll help), promessas e previsões. Forma curta: 'll. Negativa: won't.", "I'll help you.=Ajudo você.|It will rain.=Vai chover.|I won't be late.=Não vou me atrasar.", "I will to help.=I'll help.|She wills come.=She will come.", "Might = possibilidade menor: It might snow."),
'haveto': G("Have to / don't have to", "[have to / has to] + verbo base  |  [don't have to] = não precisa", "Have to expressa obrigação (has to com he/she/it). Don't have to = não é necessário; mustn't = é proibido.", "I have to work.=Tenho que trabalhar.|She has to wear a helmet.=Ela tem que usar capacete.|You don't have to come.=Você não precisa vir.", "I must to work.=I have to work.|He have to go.=He has to go.", ""),
'should': G("Conselhos: should", "sujeito + [should / shouldn't] + verbo base", "Should dá conselho: You should rest. Negativa: shouldn't. Pergunta: What should I do?", "You should sleep more.=Você deveria dormir mais.|You shouldn't worry.=Você não deveria se preocupar.|What should I do?=O que devo fazer?", "You should to rest.=You should rest.|He shoulds go.=He should go.", ""),
'perfect': G("Present perfect", "[have / has] + [particípio]", "Liga passado e presente: experiências (Have you ever…?), resultados e coisas recentes (just, already, yet). Sem data exata!", "I've been to Paris.=Já fui a Paris.|She has already left.=Ela já saiu.|I haven't finished yet.=Ainda não terminei.", "I have went there.=I have gone there.|Have you ever been in Paris? (data)=Have you ever been to Paris?", "gone ≠ been: has gone = foi e não voltou."),
'phrasal': G("Phrasal verbs", "[verbo] + [partícula]", "Phrasal verbs combinam verbo + partícula e mudam de sentido: look for (procurar), look at (olhar), turn on (ligar).", "Turn on the light.=Ligue a luz.|I'm looking for my keys.=Procuro minhas chaves.|Put on your coat.=Vista o casaco.", "Turn the light on it.=Turn the light on.|I look my keys.=I'm looking for my keys.", ""),
'reported': G("Discurso indireto", "[said (that)] + frase no passado  |  [told] + pessoa + to + verbo", "Ao contar o que alguém disse, o tempo costuma recuar: 'I am tired' → She said she was tired. Told exige a pessoa: told me.", "She said she was tired.=Ela disse que estava cansada.|He told me to wait.=Ele me disse para esperar.|They asked if I was OK.=Perguntaram se eu estava bem.", "She said me that…=She told me that…|He told to wait.=He told me to wait.", ""),
'cond1': G("Primeira condicional", "[If] + presente simples, [will] + verbo base", "Para possibilidades reais no futuro: If it rains, I'll stay home. Depois de if, não use will.", "If it rains, we'll stay home.=Se chover, ficamos em casa.|If you study, you'll pass.=Se você estudar, vai passar.|What will you do if it snows?=O que fará se nevar?", "If it will rain, I stay.=If it rains, I'll stay.|If I will have time=If I have time", ""),
'opinion': G("Opinar e concordar", "[I think] · [In my opinion] · [I agree / I don't agree]", "I think e in my opinion dão opinião. I agree concorda; I don't agree discorda. Respostas curtas: So do I, Neither do I.", "I think it's great.=Acho ótimo.|I agree with you.=Concordo com você.|Neither do I.=Eu também não.", "I am agree.=I agree.|I'm think so.=I think so.", ""),
'polite2': G("Pedidos educados: could / would", "[Could you] + verbo?   [I'd like] + algo", "Could you…? é mais educado que Can you…? I'd like soa mais cortês que I want. Use please e thank you.", "Could you help me?=Poderia me ajudar?|I'd like some water.=Gostaria de água.|Could I open the window?=Posso abrir a janela?", "You could give me the bill?=Could you give me the bill?|I want the bill.=I'd like the bill, please.", ""),
'compl': G("Reclamar com educação", "[I'm afraid] + problema  |  [Could you] + solução?", "Suavize a reclamação com I'm afraid… ou I'm sorry, but…. Depois peça uma solução com Could you…?", "I'm afraid the soup is cold.=Receio que a sopa esteja fria.|Could you change it?=Poderia trocar?|Thank you for fixing it.=Obrigado por resolver.", "This is bad!=I'm afraid there's a problem.|Change it now.=Could you change it, please?", ""),
'slang': G("Gírias e formas informais", "[gonna] = going to  ·  [wanna] = want to  ·  [gotta] = got to", "Na fala informal juntamos palavras: gonna, wanna, gotta. Na escrita formal use a forma completa.", "I'm gonna go.=Vou embora.|I wanna see it.=Quero ver.|You gotta try this!=Você tem que provar isto!", "I gonna go.=I'm gonna go.|She wanna come.=She wants to come.", "Entre amigos: tudo bem. No trabalho: prefira a forma completa."),
'idiom': G("Expressões idiomáticas", "expressão fixa = sentido figurado", "Idioms não se traduzem palavra por palavra: It's a piece of cake = é moleza. Aprenda a expressão inteira, em contexto.", "It's a piece of cake.=É moleza.|Break a leg!=Boa sorte!|I'm under the weather.=Estou meio doente.", "It's a cake piece.=It's a piece of cake.|I'm under the time.=I'm under the weather.", ""),
'social': G("Redes e e-mails", "[Dear] + nome, … [Best regards]  |  [Great photo!]", "E-mails formais abrem com Dear e fecham com Best regards. Em redes, frases curtas e exclamações: Love this! Great photo!", "Dear Omar, I'm writing to ask…=Prezado Omar, escrevo para perguntar…|Best regards, Hana.=Atenciosamente, Hana.|Love this view!=Amei esta vista!", "Dear Omar, hey=Dear Omar,|Best regard=Best regards", ""),
'story': G("Contar uma história", "[Once upon a time] · [Suddenly] · [In the end]", "Histórias usam o passado e marcadores de sequência: once upon a time, one day, suddenly, then, finally, in the end.", "Once upon a time, a fox was hungry.=Era uma vez uma raposa com fome.|Suddenly, she found a basket.=De repente, ela achou uma cesta.|In the end, they were happy.=No final, ficaram felizes.", "Once upon a time, I go.=Once upon a time, he went.|Suddenly she finds=Suddenly she found", ""),
'goodbye': G("Despedidas e metas", "[I can] + verbo + [now]  ·  [My next goal is to] + verbo", "I can… celebra o que você já sabe fazer. My next goal is to… declara um objetivo. Keep going!", "I can order food now.=Agora sei pedir comida.|My next goal is to read a book.=Minha próxima meta é ler um livro.|See you around!=A gente se vê!", "I can to order food.=I can order food.|My goal is read.=My goal is to read.", ""),
}
